    const summary = `Link "${link.title}" \u2014 ${state}. Received \u09F3${paid.toFixed(2)}` + (target != null ? ` of \u09F3${target.toFixed(2)} (remaining \u09F3${remaining.toFixed(2)})` : "") + `. ${payments?.length ?? 0} attempt(s).`;
